package com.nthexperience.desktop;

import android.app.Activity;
import android.content.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.net.Uri;
import android.os.*;
import android.view.Gravity;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;

/** Bounded, offline PDF reading. All document loading/rendering is off the UI thread. */
final class EightReader extends LinearLayout {
    static final int PICK=8501;final Activity activity;final DesktopStore store;final TextView status;final ImageView image;final ScrollView scroll;
    final ExecutorService worker=Executors.newSingleThreadExecutor();private PdfRenderer pdf;private File cached;private Bitmap bitmap;private volatile int generation;private boolean closed;private int page,count;private String uri="";private float zoom=1;
    EightReader(Activity a,DesktopStore store){super(a);activity=a;this.store=store;setOrientation(VERTICAL);setBackgroundColor(0xff3a1917);TenAppearance.preserve(this);setContentDescription("Eight PDF Reader");
        LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);for(String name:new String[]{"Open PDF","Previous","Next","Page","Zoom"}){TextView b=Aero.text(a,name,13,Color.WHITE);b.setContentDescription("Reader "+name);b.setMinHeight(dp(48));b.setPadding(dp(10),0,dp(10),0);b.setGravity(Gravity.CENTER);b.setFocusable(true);b.setOnClickListener(v->{switch(name){case "Open PDF":pick();break;case "Previous":renderPage(page-1);break;case "Next":renderPage(page+1);break;case "Page":jump();break;case "Zoom":zoom=zoom==1?1.5f:zoom==1.5f?2:1;renderPage(page);break;}});bar.addView(b);}HorizontalScrollView commands=new HorizontalScrollView(a);commands.addView(bar);addView(commands);
        status=Aero.text(a,"Open a PDF to read it here.",14,Color.WHITE);status.setPadding(dp(16),dp(10),dp(12),dp(10));addView(status);scroll=new ScrollView(a);image=new ImageView(a);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);HorizontalScrollView horizontal=new HorizontalScrollView(a);horizontal.setFillViewport(true);horizontal.addView(image,new HorizontalScrollView.LayoutParams(-1,-2));scroll.addView(horizontal,new ScrollView.LayoutParams(-1,-2));addView(scroll,new LayoutParams(-1,0,1));
        String last=store.prefs.getString("eight_reader_uri","");if(!last.isEmpty())open(Uri.parse(last));}
    int dp(int n){return Aero.dp(getContext(),n);}
    void pick(){try{activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),PICK);}catch(ActivityNotFoundException ex){status.setText("No document picker is available. Open a PDF in File Explorer.");}}
    void result(Intent data){Uri value=data.getData();if(value==null)return;try{activity.getContentResolver().takePersistableUriPermission(value,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}open(value);}
    void open(Uri value){if(closed||!"content".equals(value.getScheme()))return;uri=value.toString();int token=++generation;status.setText("Opening PDF…");String target=uri;int remembered=store.prefs.getString("eight_reader_uri","").equals(target)?store.prefs.getInt("eight_reader_page",0):0;
        worker.execute(()->{closeDocument();File temp=null;try{File folder=new File(activity.getCacheDir(),"eight-reader");folder.mkdirs();temp=File.createTempFile("document-",".pdf",folder);try(InputStream in=activity.getContentResolver().openInputStream(value);OutputStream out=new FileOutputStream(temp)){byte[] bytes=new byte[65536];int n;long size=0;while((n=in.read(bytes))!=-1){if(closed||token!=generation)throw new IOException("Canceled");if((size+=n)>100L*1024*1024)throw new IOException("PDF is larger than 100 MB");out.write(bytes,0,n);}}if(closed||token!=generation){temp.delete();return;}ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer;try{renderer=new PdfRenderer(descriptor);}catch(Exception|OutOfMemoryError error){descriptor.close();throw error;}pdf=renderer;cached=temp;int pages=renderer.getPageCount();post(()->{if(closed||token!=generation)return;count=pages;page=Math.max(0,Math.min(pages-1,remembered));store.prefs.edit().putString("eight_reader_uri",target).apply();renderPage(page);});}catch(Exception|OutOfMemoryError error){if(temp!=null)temp.delete();closeDocument();post(()->{if(!closed&&token==generation){count=0;status.setText("Cannot read this PDF. It may need a password, be damaged, exceed 100 MB, or need its file access reconnected. Choose Open PDF to try another document.");}});}});
    }
    void renderPage(int target){if(closed||count==0||target<0||target>=count)return;page=target;int token=generation;float scale=zoom;int width=Math.max(480,Math.min(1200,(int)(Math.max(getWidth(),dp(360))*scale)));int displayWidth=Math.max(dp(200),scroll.getWidth());image.setLayoutParams(new HorizontalScrollView.LayoutParams(Math.round(displayWidth*zoom),-2));status.setText("Page "+(page+1)+" of "+count+" · "+(int)(zoom*100)+"%");store.prefs.edit().putInt("eight_reader_page",page).apply();
        worker.execute(()->{if(closed||token!=generation||pdf==null)return;Bitmap next=null;try(PdfRenderer.Page p=pdf.openPage(target)){float factor=Math.min(width/(float)Math.max(1,p.getWidth()),2400f/Math.max(1,p.getHeight()));int w=Math.max(1,Math.round(p.getWidth()*factor)),h=Math.max(1,Math.round(p.getHeight()*factor));next=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);next.eraseColor(Color.WHITE);p.render(next,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}catch(Exception|OutOfMemoryError error){if(next!=null)next.recycle();post(()->{if(!closed&&token==generation)status.setText("This PDF page could not be rendered. Try another page or document.");});return;}Bitmap result=next;post(()->{if(closed||token!=generation||target!=page){result.recycle();return;}image.setImageBitmap(result);Bitmap old=bitmap;bitmap=result;if(old!=null)old.recycle();image.setContentDescription("PDF page "+(page+1)+" of "+count);scroll.scrollTo(0,0);});});}
    void jump(){if(count==0)return;EditText n=new EditText(activity);n.setInputType(2);n.setHint("1–"+count);android.app.AlertDialog d=Aero.dialog(activity).setTitle("Go to page").setView(n).setNegativeButton("Cancel",null).setPositiveButton("Go",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{int target=Integer.parseInt(n.getText().toString());if(target<1||target>count)throw new NumberFormatException();renderPage(target-1);d.dismiss();}catch(NumberFormatException ex){n.setError("Enter 1–"+count);}}));d.show();}
    private void closeDocument(){if(pdf!=null){pdf.close();pdf=null;}if(cached!=null){cached.delete();cached=null;}}
    void close(){if(closed)return;closed=true;generation++;image.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}worker.execute(this::closeDocument);worker.shutdown();}
}
